export interface BjcpStyleDetail {
  category: string;
  type: string;
  overview: string;
  aroma: string;
  appearance: string;
  flavor: string;
  mouthfeel: string;
  comments: string;
  history: string;
  historicalStyle: string;
  ingredients: string;
  comparison: string;
  examples: string;
  origin: string;
}

export interface BjcpStyle { code: string; name: string; og: [number, number]; fg: [number, number]; ibu: [number, number]; srm: [number, number]; abv: [number, number]; details?: BjcpStyleDetail }

const defaultDetail = (name: string): BjcpStyleDetail => {
  const base = name.toLowerCase();
  const type = /ipa|ale|stout|porter|brown|amber|pale|wit|saison|tripel|dubbel|lager|pils|helles|märzen|bock|weiss|alt|sour/i.test(base) ? (/ipa|ale|stout|porter|brown|amber|pale|wit|saison|tripel|dubbel|alt|sour/i.test(base) ? "Ale" : "Lager") : "Ale";
  return {
    category: name,
    type,
    overview: `Cerveja ${name.toLowerCase()} com perfil equilibrado entre malte e amargor, voltada para uma bebida limpa, saborosa e bem integrada em temperatura de serviço.`,
    aroma: `Aroma típico da categoria ${name.toLowerCase()}, com notas maltadas e de lúpulo em equilíbrio, com boa limpeza fermentativa e ausência de defeitos agressivos.`,
    appearance: `Cor e aparência compatíveis com ${name.toLowerCase()}, com boa limpidez, espuma apropriada e visual coerente com a categoria.`,
    flavor: `Sabor elegante, com malte e lúpulo trabalhando em conjunto; a intensidade depende da variação específica, mas a bebida deve ser equilibrada, seca e bem saborosa.`,
    mouthfeel: `Corpo moderado e carbonatação adequada, proporcionando sensação lisa, equilibrada e agradável na boca.`,
    comments: `Estilo clássico e bastante reconhecível dentro da família ${name.toLowerCase()}, sendo uma referência útil para comparação com receitas e equipamentos.`,
    history: `Desenvolvido como expressão tradicional do estilo ${name.toLowerCase()}, com evolução ao longo do tempo e adaptação às matérias-primas e práticas de fabricação regionais.`,
    historicalStyle: "Estilo clássico da tradição cervejeira moderna.",
    ingredients: "Maltes de base, lúpulos e levedura compatíveis com a categoria, com ajustes de moagem, fervura e fermentação para manter o perfil característico.",
    comparison: `Comparado com outras cervejas da mesma família, ${name.toLowerCase()} se distingue por seu equilíbrio de malte, coloração e amargor, mantendo identidade própria e boa drinkability.`,
    examples: "Exemplos clássicos variam conforme a categoria, mas o estilo pede referências limpas, consistentes e bem equilibradas.",
    origin: "Tradição cervejeira internacional, com variações regionais e históricos de produção bem definidos.",
  };
};

